SET local check_function_bodies = off;

CREATE EXTENSION "moddatetime" SCHEMA "extensions";

CREATE TABLE "public"."catalogues" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."catalogue_id_seq") NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "name"          text                     NOT NULL,
  "slug"          text                     NOT NULL,
  "description"   text                     NOT NULL,
  "display_order" bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."catalogue_display_order_seq") NOT NULL,
  "created_by"    uuid,
  "is_deleted"    boolean                  NOT NULL DEFAULT false,
  CONSTRAINT "catalogue_display_order_key" UNIQUE (display_order),
  CONSTRAINT "catalogue_pkey" PRIMARY KEY (id),
  CONSTRAINT "catalogue_slug_key" UNIQUE (slug),
  CONSTRAINT "slug_format" CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);

ALTER TABLE "public"."catalogues"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."exercises" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "prompt"        text                     NOT NULL,
  "created_by"    uuid,
  "is_deleted"    boolean                  NOT NULL DEFAULT false,
  "evaluation"    jsonb,
  "display_order" bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "content"       jsonb,
  "lesson_id"     bigint,
  CONSTRAINT "exercises_display_order_key" UNIQUE (display_order),
  CONSTRAINT "exercises_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."exercises"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."lessons" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "name"          text                     NOT NULL,
  "slug"          text                     NOT NULL,
  "description"   text                     NOT NULL,
  "display_order" bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_by"    uuid,
  "is_deleted"    boolean                  NOT NULL DEFAULT false,
  "theme_id"      bigint,
  CONSTRAINT "lessons_display_order_key" UNIQUE (display_order),
  CONSTRAINT "lessons_pkey" PRIMARY KEY (id),
  CONSTRAINT "lessons_slug_key" UNIQUE (slug),
  CONSTRAINT "slug_format" CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text))
);

ALTER TABLE "public"."lessons"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."themes" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "name"          text                     NOT NULL,
  "slug"          text                     NOT NULL,
  "description"   text                     NOT NULL,
  "display_order" bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_by"    uuid,
  "is_deleted"    boolean                  NOT NULL DEFAULT false,
  "catalogue_id"  bigint                   NOT NULL,
  CONSTRAINT "slug_format" CHECK ((slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'::text)),
  CONSTRAINT "themes_display_order_key" UNIQUE (display_order),
  CONSTRAINT "themes_pkey" PRIMARY KEY (id),
  CONSTRAINT "themes_slug_key" UNIQUE (slug)
);

ALTER TABLE "public"."themes"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."user_profiles" (
  "id"         uuid                     NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  "goal"       text,
  CONSTRAINT "user_profile_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."user_profiles"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "public"."content_status" AS ENUM (
  'draft',
  'published',
  'review'
);

ALTER TABLE "public"."catalogues"
  ADD COLUMN "status" public.content_status NOT NULL DEFAULT 'draft'::public.content_status;

ALTER TABLE "public"."exercises"
  ADD COLUMN "status" public.content_status NOT NULL DEFAULT 'draft'::public.content_status;

ALTER TABLE "public"."lessons"
  ADD COLUMN "status" public.content_status NOT NULL DEFAULT 'draft'::public.content_status;

ALTER TABLE "public"."themes"
  ADD COLUMN "status" public.content_status NOT NULL DEFAULT 'draft'::public.content_status;

CREATE TYPE "public"."exercise_type" AS ENUM (
  'image-to-word',
  'word-to-image',
  'multiple-choice',
  'drag-and-drop',
  'spelling'
);

ALTER TABLE "public"."exercises"
  ADD COLUMN "type" public.exercise_type NOT NULL;

CREATE TYPE "public"."user_experience_level" AS ENUM (
  'beginner',
  'elementary',
  'intermediate',
  'upper-intermediate',
  'advanced',
  'master'
);

ALTER TABLE "public"."user_profiles"
  ADD COLUMN "experience_level" public.user_experience_level;

CREATE OR REPLACE FUNCTION public.greet_world()
  RETURNS text
  LANGUAGE plpgsql
  AS $function$
BEGIN
    RETURN 'Hello, World!';
END; $function$;

CREATE OR REPLACE FUNCTION public.greet_world (
  slug text
)
  RETURNS text
  LANGUAGE plpgsql
  AS $function$
BEGIN
    RETURN slug;
END; $function$;

ALTER TABLE "public"."catalogues"
  ADD CONSTRAINT "catalogue_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."exercises"
  ADD CONSTRAINT "exercises_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."lessons"
  ADD CONSTRAINT "lessons_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."exercises"
  ADD CONSTRAINT "exercises_lesson_id_fkey" FOREIGN KEY (lesson_id) REFERENCES public.lessons(id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE "public"."themes"
  ADD CONSTRAINT "themes_catalogue_id_fkey" FOREIGN KEY (catalogue_id) REFERENCES public.catalogues(id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE "public"."themes"
  ADD CONSTRAINT "themes_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE "public"."lessons"
  ADD CONSTRAINT "lessons_theme_id_fkey" FOREIGN KEY (theme_id) REFERENCES public.themes(id) ON UPDATE CASCADE ON DELETE RESTRICT;

ALTER TABLE "public"."user_profiles"
  ADD CONSTRAINT "user_profile_id_fkey" FOREIGN KEY (id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE;

CREATE TRIGGER handle_updated_at
  BEFORE UPDATE ON public.catalogues
  FOR EACH ROW
  EXECUTE FUNCTION extensions.moddatetime();

CREATE TRIGGER handle_updated_at
  BEFORE UPDATE ON public.exercises
  FOR EACH ROW
  EXECUTE FUNCTION extensions.moddatetime('updated_at');

CREATE TRIGGER handle_updated_at
  BEFORE UPDATE ON public.lessons
  FOR EACH ROW
  EXECUTE FUNCTION extensions.moddatetime('updated_at');

CREATE TRIGGER handle_updated_at
  BEFORE UPDATE ON public.themes
  FOR EACH ROW
  EXECUTE FUNCTION extensions.moddatetime('updated_at');

CREATE TRIGGER handle_updated_at
  BEFORE UPDATE ON public.user_profiles
  FOR EACH ROW
  EXECUTE FUNCTION extensions.moddatetime('updated_at');

CREATE POLICY "Enable read access for all users" ON "public"."catalogues"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."exercises"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."lessons"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."themes"
  FOR SELECT
  TO "authenticated"
  USING (true);

CREATE POLICY "Enable read access for all users" ON "public"."user_profiles"
  FOR SELECT
  TO "authenticated"
  USING (true);

COMMENT ON EXTENSION "moddatetime" IS 'functions for tracking last modification time';

COMMENT ON TABLE "public"."catalogues" IS 'Top-level learning categories (e.g. Letters & Words)';

COMMENT ON TABLE "public"."exercises" IS 'Exercises within a lesson (questions, mcq)';

COMMENT ON TABLE "public"."lessons" IS 'Individual lessons within a theme (e.g. Introduction to Animals)';

COMMENT ON TABLE "public"."themes" IS 'Themes within a catalogue (e.g. Animals, Food)';

COMMENT ON TABLE "public"."user_profiles" IS 'User profile';

COMMENT ON TYPE "public"."content_status" IS 'Status of the content (e.g. catalogues, themes, lessions, exercises)';

COMMENT ON TYPE "public"."exercise_type" IS 'Types of exercises available to a learner';

COMMENT ON TYPE "public"."user_experience_level" IS 'Defines the experience level of a learner';

GRANT EXECUTE ON FUNCTION "public"."greet_world"() TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

GRANT EXECUTE ON FUNCTION "public"."greet_world"(text) TO PUBLIC, "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."catalogues" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."exercises" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."lessons" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."themes" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."user_profiles" TO "anon", "authenticated", "postgres", "service_role";

GRANT USAGE ON TYPE "public"."content_status" TO "postgres";

GRANT USAGE ON TYPE "public"."exercise_type" TO "postgres";

GRANT USAGE ON TYPE "public"."user_experience_level" TO "postgres";

